// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    receive() external payable {}

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, type(uint128).max);
        // fund the contract with exactly `amount`
        vm.deal(address(c), amount);
        uint256 ownerBefore = address(this).balance;
        // owner is the deployer (this test contract)
        vm.prank(c.owner());
        c.withdraw(amount);
        // Rule: withdrawing `amount` moves exactly `amount` wei to the owner.
        assertTrue(address(this).balance == ownerBefore + amount && address(c).balance == 0);
    }
}
